    "admin", "password", "123456", "default", "changeme",
    "pass", "login", "qwerty", "abc123"
}

is_vulnerable_password_value(value) {
    value.ir_type == "String"
    lower(value.value) == default_passwords[_]
}

has_credential_keyword(name) {
    contains(lower(name), credential_keywords[_])
}

contains(lower(name), keyword) {
    regex.match(sprintf(".*%s.*", [keyword]), lower(name))
}

