    regex.match(".*(vault|secret|env|var|data)\\.|\\$\\{|lookup|get_secret|data\\.", str)
} else {
    regex.match(".*(file|templatefile|filebase64)\\(", str)
}

traverse_value_for_literal(node) = true {
    walk(node, [_, n])
    n.ir_type == "String"
    n.value != ""
    not is_secret_reference(n.value)
}

check_nested_value(value) {
    value.ir_type == "String"
    is_literal_string_or_encoded(value)
} else {
    value.ir_type in {"Hash", "Array"}
    traverse_value_for_literal(value)
}

