package glitch

import data.glitch_lib

password_keywords := {"password", "passwd", "pwd", "secret", "credentials", "auth_token", "pass", "sha512_password", "sha256_password"}

# Check if name contains credential keyword (exact match, not substring)
is_credential_name(name) {
    lname := lower(name)
    some keyword
    password_keywords[keyword]
    lname == keyword
}

is_credential_name(name) {
    lname := lower(name)
    some keyword
    password_keywords[keyword]
    endswith(lname, concat("", ["_", keyword]))
}

is_credential_name(name) {
    lname := lower(name)
    some keyword
    password_keywords[keyword]
    startswith(lname, concat("", [keyword, "_"]))
}

# Check if this is a secure reference (not hard-coded)
is_secure_reference(value) {
    value.ir_type == "String"
    regex.match("^\\$\\{|.*(vault|secret|lookup|env|var|data|file|template|key)\\s*\\(|^(variable|var|local|data|module|path)\\.", value.value)
}

is_secure_reference(value) {
    value.ir_type == "VariableReference"
}

is_secure_reference(value) {
    value.ir_type == "FunctionCall"
    regex.match(".*(vault|secret|lookup|file|template|env)", value.name)
}

# Check if value is a hard-coded credential
is_hardcoded_credential(value) {
    value.ir_type == "String"
    not is_secure_reference(value)
    value.value != ""
    not regex.match("^\\$[0-9a-zA-Z]+\\$", value.value)
}

# Extract key string from Hash entry structure
get_key_string(entry, key_str) {
    entry.key.ir_type == "String"
    key_str := entry.key.value
}

# Find credential violations in Hash structures (Ansible-style)
find_credential_in_hash(node) = result {
    walk(node, [_, item])
    item.ir_type == "Hash"
    walk(item.value, [_, entry])
    entry.key
    entry.value
    get_key_string(entry, key_str)
    is_credential_name(key_str)
    is_hardcoded_credential(entry.value)
    result := entry.value
}

# Find credential violations in nested structures
find_credential_violation(node) = result {
    result := find_credential_in_hash(node)
}

# Check for dotted variable names in Chef-style (e.g., default.serv.password)
is_dotted_credential_variable(name) {
    parts := split(name, ".")
    some i
    part := parts[i]
    cleaned := trim(part, "[]'\"")
    is_credential_name(cleaned)
}

# Check if type is Hash or Array
